begin;
create table if not exists clientes_backup_recuperacao_20260721 as select * from clientes;
drop table if exists recovery_clientes_20260721;
create table recovery_clientes_20260721 (agendor_codigo text, cnpj text, vendedor_id integer, origem text);
select origem, vendedor_id, count(*) as registros from recovery_clientes_20260721 group by origem, vendedor_id order by vendedor_id;
with matches as (select c.id, array_agg(distinct r.vendedor_id) as vendedores from clientes c join recovery_clientes_20260721 r on (r.agendor_codigo <> '' and c.agendor_codigo = r.agendor_codigo) or (r.cnpj <> '' and regexp_replace(coalesce(c.cnpj, ''), '\D', '', 'g') = r.cnpj) group by c.id), seguros as (select id, vendedores[1] as vendedor_id from matches where cardinality(vendedores) = 1) update clientes c set vendedor_id = s.vendedor_id, atualizado_em = now() from seguros s where c.id = s.id and c.vendedor_id is distinct from s.vendedor_id returning c.id, c.razao_social, c.vendedor_id;
commit;
